import { tallyParticipantResults } from '../../../query/matchUps/roundRobinTally/tallyParticipantResults.mjs';
import { setFirstClassOrExtension } from '../../extensions/setFirstClassOrExtension.mjs';
import { getPolicyDefinitions } from '../../../query/extensions/getAppliedPolicies.mjs';
import { modifyDrawNotice } from '../../notifications/drawNotifications.mjs';
import { createSubOrderMap } from '../../../query/structure/createSubOrderMap.mjs';
import { validMatchUps } from '../../../validators/validMatchUp.mjs';
import { POLICY_TYPE_ROUND_ROBIN_TALLY } from '../../../constants/policyConstants.mjs';
import { INVALID_VALUES } from '../../../constants/errorConditionConstants.mjs';
import { TALLY, SUB_ORDER } from '../../../constants/extensionConstants.mjs';
import { SUCCESS } from '../../../constants/resultConstants.mjs';

function updateAssignmentParticipantResults({ positionAssignments, tournamentRecord, drawDefinition, matchUpFormat, matchUps, event, }) {
    if (!validMatchUps(matchUps))
        return { error: INVALID_VALUES };
    if (!positionAssignments)
        return { error: INVALID_VALUES };
    const { policyDefinitions } = getPolicyDefinitions({
        policyTypes: [POLICY_TYPE_ROUND_ROBIN_TALLY],
        tournamentRecord,
        drawDefinition,
        event,
    });
    const { subOrderMap } = createSubOrderMap({ positionAssignments });
    const result = matchUps.length
        ? tallyParticipantResults({
            policyDefinitions,
            matchUpFormat,
            subOrderMap,
            matchUps,
        })
        : undefined;
    if (result?.error)
        return result;
    const { participantResults = {}, bracketComplete, report } = result ?? {};
    const participantIds = Object.keys(participantResults);
    positionAssignments.forEach((assignment) => {
        const { participantId } = assignment;
        if (participantIds.includes(participantId)) {
            setFirstClassOrExtension({
                value: participantResults[participantId],
                element: assignment,
                attribute: 'tally',
                name: TALLY,
            });
            if (!participantResults[participantId].ties) {
                setFirstClassOrExtension({
                    element: assignment,
                    attribute: 'subOrder',
                    name: SUB_ORDER,
                    value: undefined,
                });
            }
        }
        else {
            setFirstClassOrExtension({
                element: assignment,
                attribute: 'tally',
                name: TALLY,
                value: undefined,
            });
            setFirstClassOrExtension({
                element: assignment,
                attribute: 'subOrder',
                name: SUB_ORDER,
                value: undefined,
            });
        }
    });
    modifyDrawNotice({ drawDefinition });
    return {
        ...SUCCESS,
        participantResults,
        bracketComplete,
        report,
    };
}

export { updateAssignmentParticipantResults };
