import { updateAssignmentParticipantResults } from '../drawDefinitions/matchUpGovernor/updateAssignmentParticipantResults.mjs';
import { deleteMatchUpsNotice, modifyMatchUpNotice, modifyDrawNotice } from '../notifications/drawNotifications.mjs';
import { checkRequiredParameters } from '../../helpers/parameters/checkRequiredParameters.mjs';
import { getAllStructureMatchUps } from '../../query/matchUps/getAllStructureMatchUps.mjs';
import { checkScoreHasValue } from '../../query/matchUp/checkScoreHasValue.mjs';
import { getAdHocStructureDetails } from './getAdHocStructureDetails.mjs';
import { unique, getMissingSequenceNumbers } from '../../tools/arrays.mjs';
import { getMatchUpId } from '../../functions/global/extractors.mjs';
import { isAdHoc } from '../../query/drawDefinition/isAdHoc.mjs';
import { xa } from '../../tools/extractAttributes.mjs';
import { ARRAY, DRAW_DEFINITION, OF_TYPE, INVALID, ONE_OF, MATCHUP_IDS } from '../../constants/attributeConstants.mjs';
import { INVALID_VALUES, SCORES_PRESENT } from '../../constants/errorConditionConstants.mjs';
import { TEAM_MATCHUP } from '../../constants/matchUpTypes.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function deleteAdHocMatchUps(params) {
    const paramsCheck = checkRequiredParameters(params, [
        { [DRAW_DEFINITION]: true },
        {
            [ONE_OF]: { [MATCHUP_IDS]: false, roundNumbers: false },
            [INVALID]: INVALID_VALUES,
            [OF_TYPE]: ARRAY,
        },
    ]);
    if (paramsCheck.error)
        return paramsCheck;
    const { removeIncomplete = false, removeUnAssigned = true, removeCompleted = false, tournamentRecord, drawDefinition, event, } = params;
    const structureResult = getAdHocStructureDetails(params);
    if (structureResult.error)
        return structureResult;
    const { structure, structureId, existingMatchUps, matchUpIds } = structureResult;
    const matchUpIdsWithScoreValue = [];
    const matchUpsToDelete = existingMatchUps?.filter(({ matchUpId, score, winningSide }) => {
        if (winningSide && !removeCompleted)
            return false;
        if (winningSide || checkScoreHasValue({ score })) {
            if (!winningSide && !removeIncomplete)
                return false;
            matchUpIdsWithScoreValue.push(matchUpId);
        }
        else if (!removeUnAssigned)
            return false;
        return matchUpIds?.includes(matchUpId);
    }) ?? [];
    const matchUpIdsToDelete = matchUpsToDelete.map(getMatchUpId);
    const tieMatchUpIdsToDelete = matchUpsToDelete
        .map(({ tieMatchUps }) => tieMatchUps?.map(getMatchUpId))
        .filter(Boolean)
        .flat();
    if (matchUpIdsToDelete.length) {
        structure.matchUps = (structure.matchUps ?? []).filter(({ matchUpId }) => !matchUpIdsToDelete.includes(matchUpId));
        deleteMatchUpsNotice({
            tournamentId: tournamentRecord?.tournamentId,
            matchUpIds: [...tieMatchUpIdsToDelete, ...matchUpIdsToDelete],
            action: 'deleteAdHocMatchUps',
            eventId: event?.eventId,
            drawDefinition,
        });
        const roundNumbers = unique(structure.matchUps.map(xa('roundNumber')));
        const missingRoundNumbers = getMissingSequenceNumbers(roundNumbers);
        if (missingRoundNumbers.length) {
            missingRoundNumbers.reverse();
            for (const roundNumber of missingRoundNumbers) {
                structure.matchUps.forEach((matchUp) => {
                    if (matchUp.roundNumber && matchUp.roundNumber > roundNumber) {
                        matchUp.roundNumber -= 1;
                        modifyMatchUpNotice({
                            tournamentId: tournamentRecord?.tournamentId,
                            context: ['adHoc round deletion'],
                            eventId: event?.eventId,
                            event,
                            drawDefinition,
                            matchUp,
                        });
                    }
                });
            }
        }
        if (matchUpIdsWithScoreValue.length) {
            structure.positionAssignments = unique(structure.matchUps
                .flatMap((matchUp) => (matchUp.sides ?? []).map((side) => side.participantId))
                .filter(Boolean)).map((participantId) => ({ participantId }));
            const matchUpFormat = structure?.matchUpFormat ?? drawDefinition?.matchUpFormat ?? event?.matchUpFormat;
            const isDualMatchUp = structureResult.existingMatchUps.some((matchUp) => matchUp.matchUpType === TEAM_MATCHUP);
            const matchUpFilters = isDualMatchUp ? { matchUpTypes: [TEAM_MATCHUP] } : undefined;
            const { matchUps } = getAllStructureMatchUps({
                afterRecoveryTimes: false,
                inContext: true,
                matchUpFilters,
                structure,
                event,
            });
            const isAdHocStructure = isAdHoc({ structure });
            if (isAdHocStructure) {
                structure.positionAssignments = unique(matchUps.flatMap((matchUp) => (matchUp.sides ?? []).map((side) => side.participantId)).filter(Boolean)).map((participantId) => ({ participantId }));
            }
            const result = updateAssignmentParticipantResults({
                positionAssignments: structure.positionAssignments,
                tournamentRecord,
                drawDefinition,
                matchUpFormat,
                matchUps,
                event,
            });
            if (result.error)
                console.log(result);
        }
        modifyDrawNotice({
            structureIds: [structureId],
            eventId: event?.eventId,
            drawDefinition,
        });
    }
    if (!matchUpIdsToDelete.length && matchUpIds.length)
        return { error: SCORES_PRESENT };
    return { ...SUCCESS, deletedMatchUpsCount: [...matchUpIdsToDelete, ...tieMatchUpIdsToDelete].length };
}

export { deleteAdHocMatchUps };
