import { setParticipantScaleItem } from '../participants/scaleItems/addScaleItems.mjs';
import { getTournamentPoints } from '../../query/scales/getTournamentPoints.mjs';
import { MISSING_TOURNAMENT_RECORD } from '../../constants/errorConditionConstants.mjs';
import { RANKING } from '../../constants/scaleConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function applyTournamentRankingPoints({ tournamentRecord, policyDefinitions, participantFilters, scaleName = 'RANKING_POINTS', level, removePriorValues, }) {
    if (!tournamentRecord)
        return { error: MISSING_TOURNAMENT_RECORD };
    const pointsResult = getTournamentPoints({
        tournamentRecord,
        policyDefinitions,
        participantFilters,
        level,
    });
    if (pointsResult.error)
        return pointsResult;
    const { personPoints, pairPoints, teamPoints } = pointsResult;
    const personToParticipantMap = {};
    for (const participant of tournamentRecord.participants ?? []) {
        if (participant.person?.personId) {
            personToParticipantMap[participant.person.personId] = participant.participantId;
        }
    }
    const scaleDate = tournamentRecord.endDate;
    let modificationsApplied = 0;
    for (const [personId, awards] of Object.entries(personPoints)) {
        const participantId = personToParticipantMap[personId];
        if (!participantId)
            continue;
        const byEventType = {};
        for (const award of awards) {
            const et = award.eventType || 'SINGLES';
            if (!byEventType[et])
                byEventType[et] = [];
            byEventType[et].push(award);
        }
        for (const [eventType, eventAwards] of Object.entries(byEventType)) {
            const totalPoints = eventAwards.reduce((sum, a) => sum + (a.points || 0) + (a.qualityWinPoints || 0) + (a.linePoints || 0), 0);
            const scaleItem = {
                scaleType: RANKING,
                scaleName,
                eventType: eventType,
                scaleDate,
                scaleValue: { points: totalPoints, awards: eventAwards },
            };
            const writeResult = setParticipantScaleItem({
                tournamentRecord,
                participantId,
                scaleItem,
                removePriorValues,
            });
            if (writeResult.error)
                return writeResult;
            modificationsApplied++;
        }
    }
    return {
        ...SUCCESS,
        personPoints,
        pairPoints,
        teamPoints,
        modificationsApplied,
    };
}

export { applyTournamentRankingPoints };
