import { getAllStructureMatchUps } from '../../../query/matchUps/getAllStructureMatchUps.mjs';
import { modifyMatchUpScore } from '../score/modifyMatchUpScore.mjs';
import { getPositionAssignments } from '../../../query/drawDefinition/positionsGetter.mjs';
import { modifyMatchUpNotice } from '../../notifications/drawNotifications.mjs';
import { getDevContext } from '../../../global/state/globalState.mjs';

function swapWinnerLoser(params) {
    const { tournamentRecord, inContextMatchUp, structure, drawDefinition, event } = params;
    const matchUpRoundNumber = inContextMatchUp.roundNumber;
    const existingWinnerSide = inContextMatchUp.sides.find((side) => side.sideNumber === inContextMatchUp.winningSide);
    const existingLoserSide = inContextMatchUp.sides.find((side) => side.sideNumber !== inContextMatchUp.winningSide);
    const { drawPosition: existingWinnerDrawPosition, participantId: existingWinnerParticipantId } = existingWinnerSide;
    const { drawPosition: existingLoserDrawPosition, participantId: existingLoserParticipantId } = existingLoserSide;
    const stack = 'swapWinnerLoser';
    const { matchUps } = getAllStructureMatchUps(params);
    const existingWinnerSubsequentMatchUps = matchUps.filter(({ drawPositions, roundNumber }) => drawPositions?.includes(existingWinnerDrawPosition) && roundNumber > matchUpRoundNumber);
    if (getDevContext({ changeWinner: true }))
        console.log({ existingWinnerSubsequentMatchUps });
    existingWinnerSubsequentMatchUps.forEach((matchUp) => {
        matchUp.drawPositions =
            matchUp.drawPositions?.map((drawPosition) => drawPosition === existingWinnerDrawPosition ? existingLoserDrawPosition : drawPosition) ?? [];
        modifyMatchUpNotice({
            tournamentId: tournamentRecord?.tournamentId,
            eventId: params.event?.eventId,
            context: stack,
            drawDefinition,
            matchUp,
            event,
        });
    });
    const { stage: currentStage, stageSequence: currentStageSequence } = structure;
    const subsequentStructureIds = drawDefinition.structures
        .filter(({ stage, stageSequence }) => stage === currentStage && stageSequence > currentStageSequence)
        .map(({ structureId }) => structureId);
    const { targetLinks: { loserTargetLink, winnerTargetLink }, } = params.targetData;
    const targetStructureIds = [loserTargetLink?.target.structureId, winnerTargetLink?.target?.structureId].filter(Boolean);
    drawDefinition.structures
        .filter(({ stage, structureId }) => {
        return stage !== currentStage && targetStructureIds.includes(structureId);
    })
        .forEach(({ stage: targetStage, stageSequence: targetStageSequence, structureId }) => {
        if (!subsequentStructureIds.includes(structureId))
            subsequentStructureIds.push(structureId);
        drawDefinition.structures
            .filter(({ stage, stageSequence }) => stage === targetStage && stageSequence > targetStageSequence)
            .forEach(({ structureId }) => {
            if (!subsequentStructureIds.includes(structureId))
                subsequentStructureIds.push(structureId);
        });
    });
    const subsequentStructures = drawDefinition.structures.filter(({ structureId }) => subsequentStructureIds.includes(structureId));
    subsequentStructures.forEach((structure) => {
        const { positionAssignments } = getPositionAssignments({ structure });
        const existingWinnerAssignment = positionAssignments?.find(({ participantId }) => participantId === existingWinnerParticipantId);
        const existingLoserAssignment = positionAssignments?.find(({ participantId }) => participantId === existingLoserParticipantId);
        if (existingWinnerAssignment)
            existingWinnerAssignment.participantId = existingLoserParticipantId;
        if (existingLoserAssignment)
            existingLoserAssignment.participantId = existingWinnerParticipantId;
    });
    return modifyMatchUpScore({ ...params});
}

export { swapWinnerLoser };
