import { conflictInputsFrom } from './conflictEvaluationInputs.mjs';
import { getOfficialConflicts } from './getOfficialConflicts.mjs';
import { getParticipants } from '../participants/getParticipants.mjs';
import { findDrawMatchUp } from '../../acquire/findDrawMatchUp.mjs';
import { MISSING_TOURNAMENT_RECORD, MISSING_MATCHUP_ID } from '../../constants/errorConditionConstants.mjs';
import { MISSING_CONFLICT_SOURCE } from '../../constants/officiatingConstants.mjs';
import { GROUP } from '../../constants/participantConstants.mjs';
import { POLICY_TYPE_OFFICIATING_CONFLICT } from '../../constants/policyConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function getMatchUpOfficialConflicts(params) {
    const { officialParticipantId, policyDefinitions, tournamentRecord, drawDefinition, officialRecord, matchUpId, event, } = params;
    if (!tournamentRecord)
        return { error: MISSING_TOURNAMENT_RECORD };
    if (!matchUpId)
        return { error: MISSING_MATCHUP_ID };
    if (!officialRecord && !officialParticipantId)
        return { error: MISSING_CONFLICT_SOURCE };
    if (!policyDefinitions?.[POLICY_TYPE_OFFICIATING_CONFLICT]) {
        return { ...SUCCESS, conflicts: [], blocked: false, checkedParticipants: [] };
    }
    const tournamentParticipants = getParticipants({ tournamentRecord }).participants ?? [];
    const result = findDrawMatchUp({
        tournamentParticipants,
        inContext: true,
        drawDefinition,
        matchUpId,
        event,
    });
    if (result.error)
        return { error: result.error };
    const sideParticipantIds = (result.matchUp?.sides ?? [])
        .map((side) => side?.participantId)
        .filter(Boolean);
    const participantMap = new Map(tournamentParticipants.map((participant) => [participant.participantId, participant]));
    const checkedParticipants = [];
    const seen = new Set();
    const include = (participantId) => {
        if (!participantId || seen.has(participantId))
            return;
        const participant = participantMap.get(participantId);
        if (!participant)
            return;
        seen.add(participantId);
        checkedParticipants.push(participant);
        for (const individualParticipantId of participant.individualParticipantIds ?? [])
            include(individualParticipantId);
    };
    for (const participantId of sideParticipantIds)
        include(participantId);
    const groupParticipants = tournamentParticipants.filter((participant) => participant.participantType === GROUP);
    const conflictResult = getOfficialConflicts({
        ...conflictInputsFrom(params),
        participants: checkedParticipants,
        groupParticipants,
    });
    if (conflictResult.error)
        return { error: conflictResult.error };
    return { ...SUCCESS, conflicts: conflictResult.conflicts, blocked: conflictResult.blocked, checkedParticipants };
}

export { getMatchUpOfficialConflicts };
