import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { findCourt } from './findCourt.mjs';
import { makeDeepCopy } from '../../tools/makeDeepCopy.mjs';
import { TOURNAMENT_RECORD, COURT_ID } from '../../constants/attributeConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function getCourtInfo({ tournamentRecord, internalUse, courtId }) {
    const paramsCheck = requireParams({ tournamentRecord, courtId }, [TOURNAMENT_RECORD, COURT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    const result = findCourt({ tournamentRecord, courtId });
    if (result.error)
        return result;
    const courtInfo = result.court &&
        (({ altitude, courtId, courtName, courtDimensions, latitude, longitude, surfaceCategory, surfaceType, surfacedDate, pace, notes, }) => ({
            altitude,
            courtId,
            courtName,
            courtDimensions,
            latitude,
            longitude,
            surfaceCategory,
            surfaceType,
            surfacedDate,
            pace,
            notes,
        }))(result.court);
    return { ...SUCCESS, courtInfo: makeDeepCopy(courtInfo, false, internalUse) };
}

export { getCourtInfo };
