import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { findPracticeBooking } from './findPracticeBooking.mjs';
import { addNotice } from '../../global/state/globalState.mjs';
import { INVALID_VALUES, REGISTRATION_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';
import { TOURNAMENT_RECORD, COURT_ID } from '../../constants/attributeConstants.mjs';
import { MODIFY_VENUE } from '../../constants/topicConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function removePracticeRegistration(params) {
    const { tournamentRecord, courtId, date, bookingId, registrationId, disableNotice, occurredAt } = params;
    const paramsCheck = requireParams({ tournamentRecord, courtId }, [TOURNAMENT_RECORD, COURT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!date)
        return { error: INVALID_VALUES, info: 'date is required' };
    if (!bookingId)
        return { error: INVALID_VALUES, info: 'bookingId is required' };
    if (!registrationId)
        return { error: INVALID_VALUES, info: 'registrationId is required' };
    const found = findPracticeBooking({ tournamentRecord, courtId, date, bookingId });
    if (found.error)
        return { error: found.error };
    const { booking, venue } = found;
    if (!booking)
        return { error: INVALID_VALUES, info: 'booking lookup returned no booking' };
    const index = booking.registrations?.findIndex((r) => r.registrationId === registrationId) ?? -1;
    if (index < 0)
        return { error: REGISTRATION_NOT_FOUND };
    booking.registrations.splice(index, 1);
    booking.updatedAt = occurredAt ?? new Date().toISOString();
    if (!disableNotice && venue) {
        addNotice({
            payload: { venue, tournamentId: tournamentRecord.tournamentId },
            topic: MODIFY_VENUE,
            key: venue.venueId,
        });
    }
    return { ...SUCCESS };
}

export { removePracticeRegistration };
