import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { overlap } from '../../tools/arrays.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { TEAM, PAIR } from '../../constants/participantConstants.mjs';

function getParticipantEventDetails({ tournamentRecord, participantId, }) {
    const paramsCheck = requireParams({ tournamentRecord, participantId }, [TOURNAMENT_RECORD, PARTICIPANT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    const relevantParticipantIds = [participantId].concat((tournamentRecord.participants ?? [])
        .filter((participant) => participant?.participantType &&
        [TEAM, PAIR].includes(participant.participantType) &&
        participant.individualParticipantIds?.includes(participantId))
        .map((participant) => participant.participantId));
    const relevantEvents = (tournamentRecord.events ?? [])
        .filter((event) => {
        const enteredParticipantIds = (event?.entries ?? []).map((entry) => entry.participantId);
        return overlap(enteredParticipantIds, relevantParticipantIds);
    })
        .map((event) => ({ eventName: event.eventName, eventId: event.eventId }));
    return { eventDetails: relevantEvents };
}

export { getParticipantEventDetails };
