import { getPositionAssignments } from '../../../query/drawDefinition/positionsGetter.mjs';
import { addExtension } from '../../extensions/addExtension.mjs';
import { findExtension } from '../../../acquire/findExtension.mjs';
import { POSITION_ACTIONS } from '../../../constants/extensionConstants.mjs';
import { MAIN } from '../../../constants/drawDefinitionConstants.mjs';

function addPositionActionTelemetry(params) {
    const { appliedPolicies, positionAction, drawDefinition } = params;
    if (appliedPolicies?.audit?.[POSITION_ACTIONS] === false)
        return;
    const { extension } = findExtension({
        name: POSITION_ACTIONS,
        element: drawDefinition,
    });
    const existingValue = Array.isArray(extension?.value) ? (extension?.value ?? []) : [];
    if (!existingValue?.length) {
        const mainStructure = drawDefinition.structures.find((structure) => structure.stage === MAIN);
        if (mainStructure) {
            const initialAssignments = getPositionAssignments({
                structure: mainStructure,
            }).positionAssignments?.map(({ drawPosition, participantId, bye, qualifier }) => ({
                drawPosition,
                participantId,
                qualifier,
                bye,
            }));
            existingValue.push({
                name: 'initialMainAssignments',
                initialAssignments,
            });
        }
    }
    const updatedExtension = {
        value: existingValue.concat(positionAction),
        name: POSITION_ACTIONS,
    };
    addExtension({ element: drawDefinition, extension: updatedExtension });
}

export { addPositionActionTelemetry };
