import { getAccessorValue } from '../../tools/getAccessorValue.mjs';
import { addNotice } from '../../global/state/globalState.mjs';
import { addExtension } from '../extensions/addExtension.mjs';
import { findExtension } from '../../acquire/findExtension.mjs';
import { UUID } from '../../tools/UUID.mjs';
import { MISSING_TOURNAMENT_RECORD, NO_PARTICIPANTS_GENERATED } from '../../constants/errorConditionConstants.mjs';
import { GROUPING_ATTRIBUTE } from '../../constants/extensionConstants.mjs';
import { INDIVIDUAL, TEAM } from '../../constants/participantConstants.mjs';
import { ADD_PARTICIPANTS } from '../../constants/topicConstants.mjs';
import { COMPETITOR } from '../../constants/participantRoleValues.mjs';
