import { calculatePeriodLength } from '../../../../assemblies/generators/scheduling/utils/calculatePeriodLength.mjs';
import { sameDay, timeStringMinutes, extractTime, addMinutesToTimeString } from '../../../../tools/dateTime.mjs';
import { matchUpFormatTimes } from '../../../../query/extensions/matchUpFormatTiming/getMatchUpFormatTiming.mjs';
import { getScheduleTiming } from '../../../../query/extensions/matchUpFormatTiming/getScheduleTiming.mjs';
import { competitionScheduleMatchUps } from '../../../../query/matchUps/competitionScheduleMatchUps.mjs';
import { getVenuesAndCourts } from '../../../../query/venues/venuesAndCourtsGetter.mjs';
import { getMatchUpId } from '../../../../functions/global/extractors.mjs';
import { getScheduleTimes } from '../../../../query/venues/getScheduleTimes.mjs';
import { MISSING_TOURNAMENT_RECORDS } from '../../../../constants/errorConditionConstants.mjs';

function calculateScheduleTimes({ calculateStartTimeFromCourts = true, defaultRecoveryMinutes = 0, averageMatchUpMinutes = 90, remainingScheduleTimes, clearScheduleDates, tournamentRecords, periodLength, scheduleDate, startTime, venueIds, endTime, }) {
    if (typeof tournamentRecords !== 'object' || !Object.keys(tournamentRecords).length)
        return { error: MISSING_TOURNAMENT_RECORDS };
    periodLength =
        periodLength ??
            calculatePeriodLength({
                recoveryMinutes: defaultRecoveryMinutes,
                averageMatchUpMinutes,
            });
    const { courts: allCourts, venues } = getVenuesAndCourts({
        dates: [scheduleDate],
        ignoreDisabled: true,
        tournamentRecords,
    });
    const courts = allCourts?.filter((court) => !venueIds || venueIds.includes(court.venueId));
    if (!startTime) {
        startTime = courts?.reduce((minStartTime, court) => {
            const dateAvailability = court.dateAvailability?.find((availability) => !availability.date || sameDay(scheduleDate, availability.date));
            const comparisonStartTime = dateAvailability?.startTime ?? court.startTime;
            return comparisonStartTime &&
                (!minStartTime || timeStringMinutes(comparisonStartTime) < timeStringMinutes(minStartTime))
                ? comparisonStartTime
                : minStartTime;
        }, undefined);
    }
    if (!endTime) {
        endTime = courts?.reduce((maxEndTime, court) => {
            const dateAvailability = court.dateAvailability?.find((availability) => !availability.date || sameDay(scheduleDate, availability.date));
            const comparisonEndTime = dateAvailability?.endTime ?? court.endTime;
            return comparisonEndTime && (!maxEndTime || timeStringMinutes(comparisonEndTime) > timeStringMinutes(maxEndTime))
                ? comparisonEndTime
                : maxEndTime;
        }, undefined);
    }
    const tournaments = Object.values(tournamentRecords);
    const eventDetails = Object.assign({}, ...tournaments
        .map((tournamentRecord) => (tournamentRecord.events ?? []).map((event) => {
        const { scheduleTiming } = getScheduleTiming({
            tournamentRecord,
            event,
        });
        return {
            [event.eventId]: { event, scheduleTiming },
        };
    }))
        .flat());
    const matchUpFilters = { scheduledDate: scheduleDate, venueIds };
    const matchUpsWithSchedule = competitionScheduleMatchUps({
        sortDateMatchUps: false,
        tournamentRecords,
        matchUpFilters,
    });
    const dateMatchUps = matchUpsWithSchedule?.dateMatchUps ?? [];
    const completedMatchUps = matchUpsWithSchedule?.completedMatchUps ?? [];
    const relevantMatchUps = [];
    relevantMatchUps.push(...dateMatchUps);
    relevantMatchUps.push(...completedMatchUps);
    const defaultTiming = {
        averageTimes: [{ minutes: { default: averageMatchUpMinutes } }],
        recoveryTimes: [{ minutes: { default: defaultRecoveryMinutes } }],
    };
    const bookings = relevantMatchUps?.map(({ eventId, schedule, matchUpFormat }) => {
        const { event, scheduleTiming } = eventDetails[eventId];
        const eventType = event?.eventType;
        const timingDetails = {
            ...scheduleTiming,
            defaultTiming,
            matchUpFormat,
        };
        const { averageMinutes, recoveryMinutes } = matchUpFormatTimes({
            eventType,
            timingDetails,
        });
        const { courtId, venueId } = schedule;
        const startTime = extractTime(schedule.scheduledTime);
        const endTime = addMinutesToTimeString(startTime, averageMinutes);
        return {
            recoveryMinutes,
            averageMinutes,
            periodLength,
            startTime,
            endTime,
            courtId,
            venueId,
        };
    });
    const timingParameters = {
        calculateStartTimeFromCourts,
        remainingScheduleTimes,
        averageMatchUpMinutes,
        date: scheduleDate,
        clearScheduleDates,
        periodLength,
        startTime,
        endTime,
        bookings,
        courts,
    };
    const { scheduleTimes } = getScheduleTimes(timingParameters);
    const venueId = (venueIds?.length === 1 && venueIds[0]) || (venues?.length === 1 && venues[0].venueId) || undefined;
    const dateScheduledMatchUpIds = relevantMatchUps.map(getMatchUpId);
    return { venueId, scheduleTimes, dateScheduledMatchUpIds };
}

export { calculateScheduleTimes };
