import { getMatchUpDependencies } from '../../../../../query/matchUps/getMatchUpDependencies.mjs';
import { generateRange, unique, instanceCount } from '../../../../../tools/arrays.mjs';
import { matchUpSort } from '../../../../../functions/sorters/matchUpSort.mjs';
import { validMatchUps } from '../../../../../validators/validMatchUp.mjs';
import { ensureInt } from '../../../../../tools/ensureInt.mjs';
import { MISSING_MATCHUPS, MISSING_CONTEXT } from '../../../../../constants/errorConditionConstants.mjs';
import { BYE } from '../../../../../constants/matchUpStatusValues.mjs';
import { SCHEDULE_STATE, CONFLICT_COURT_DOUBLE_BOOKING, SCHEDULE_CONFLICT, CONFLICT_PARTICIPANTS, SCHEDULE_WARNING, CONFLICT_POTENTIAL_PARTICIPANTS, SCHEDULE_ISSUE_IDS, CONFLICT_MATCHUP_ORDER, SCHEDULE_ERROR, SCHEDULE_ISSUE, CONFLICT_BYE_SCHEDULED, CONFLICT_POSITION_LINK } from '../../../../../constants/scheduleConstants.mjs';

