        sourceMatchUpIds.length && profile.sourceMatchUpIds.push(...sourceMatchUpIds);
        const matchUpParticipantIds = sides
            ?.flatMap((side) => [side.participant?.individualParticipantIds, side.participantId])
            .flat()
            .filter(Boolean) ?? [];
