import { checkRequiredParameters } from '../../helpers/parameters/checkRequiredParameters.mjs';
import { getPairedParticipant } from '../../query/participant/getPairedParticipant.mjs';
import { getParticipantId } from '../../functions/global/extractors.mjs';
import { addParticipants } from '../participants/addParticipants.mjs';
import { stringSort } from '../../functions/sorters/stringSort.mjs';
import { addNotice } from '../../global/state/globalState.mjs';
import { intersection } from '../../tools/arrays.mjs';
import { addEventEntries } from './addEventEntries.mjs';
import { UUID } from '../../tools/UUID.mjs';
import { INVALID_EVENT_TYPE, INVALID_PARTICIPANT_IDS } from '../../constants/errorConditionConstants.mjs';
import { EVENT, TOURNAMENT_RECORD } from '../../constants/attributeConstants.mjs';
import { INDIVIDUAL, PAIR } from '../../constants/participantConstants.mjs';
import { ADD_PARTICIPANTS } from '../../constants/topicConstants.mjs';
import { ALTERNATE } from '../../constants/entryStatusValues.mjs';
import { COMPETITOR } from '../../constants/participantRoleValues.mjs';
import { MAIN } from '../../constants/drawDefinitionConstants.mjs';
import { DOUBLES } from '../../constants/matchUpTypes.mjs';
import { isMale } from '../../validators/isMale.mjs';
import { isFemale } from '../../validators/isFemale.mjs';
import { isMixed } from '../../validators/isMixed.mjs';
import { isAny } from '../../validators/isAny.mjs';

function addEventEntryPairs(params) {
    const paramsCheck = checkRequiredParameters(params, [{ [TOURNAMENT_RECORD]: true, [EVENT]: true }]);
    if (paramsCheck.error)
        return paramsCheck;
    const { allowDuplicateParticipantIdPairs, entryStatus = ALTERNATE, participantIdPairs = [], entryStage = MAIN, tournamentRecord, enforceCategory, drawDefinition, event, uuids, } = params;
    if (event.eventType !== DOUBLES)
        return { error: INVALID_EVENT_TYPE };
    const existingParticipantIdPairs = [];
    const genderMap = new Map();
    for (const participant of tournamentRecord.participants ?? []) {
        const { participantType, participantId, person, individualParticipantIds } = participant;
        if (participantType === INDIVIDUAL && person?.sex) {
            genderMap.set(participantId, person.sex);
        }
        else if (participantType === PAIR && individualParticipantIds) {
            existingParticipantIdPairs.push(individualParticipantIds);
        }
    }
    const invalidParticipantIdPairs = participantIdPairs.filter((pair) => {
        if (pair.length !== 2)
            return true;
        if (!event.gender || isAny(event.gender))
            return false;
        if (!genderMap.has(pair[0]) || !genderMap.has(pair[1]))
            return true;
        const participantGenders = pair.map((id) => genderMap.get(id));
        let invalidParticiapntGenders = (isMale(event.gender) && (!isMale(participantGenders[0]) || !isMale(participantGenders[1]))) ||
            (isFemale(event.gender) && (!isFemale(participantGenders[0]) || !isFemale(participantGenders[1])));
        if (isMixed(event.gender)) {
            participantGenders.sort(stringSort);
            if (!isFemale(participantGenders[0]) || !isMale(participantGenders[1]))
                invalidParticiapntGenders = true;
        }
        return invalidParticiapntGenders;
    });
    if (invalidParticipantIdPairs.length)
        return { error: INVALID_PARTICIPANT_IDS, invalidParticipantIdPairs };
    const provisionalParticipants = participantIdPairs.map((individualParticipantIds) => ({
        participantId: uuids?.pop() ?? UUID(),
        participantRole: COMPETITOR,
        individualParticipantIds,
        participantType: PAIR,
    }));
    const newParticipants = allowDuplicateParticipantIdPairs
        ? provisionalParticipants
        : provisionalParticipants.filter((participant) => {
            return !existingParticipantIdPairs.some((existing) => intersection(existing, participant.individualParticipantIds).length === 2);
        });
    let info;
    let addedParticipants = [];
    if (newParticipants) {
        const result = addParticipants({
            allowDuplicateParticipantIdPairs,
            participants: newParticipants,
            returnParticipants: true,
            tournamentRecord,
        });
        if (result.error)
            return result;
        addedParticipants = result.participants ?? [];
        info = result.info;
    }
    const pairParticipantIds = participantIdPairs
        .map((participantIds) => {
        const addedParticipant = addedParticipants.find((addedPair) => intersection(addedPair.individualParticipantIds, participantIds).length === 2);
        if (addedParticipant)
            return addedParticipant;
        const { participant } = getPairedParticipant({
            tournamentRecord,
            participantIds,
        });
        return participant;
    })
        .map((participant) => participant.participantId);
    const result = addEventEntries({
        participantIds: pairParticipantIds,
        tournamentRecord,
        enforceCategory,
        drawDefinition,
        entryStatus,
        entryStage,
        event,
    });
    if (newParticipants.length) {
        addNotice({
            payload: { participants: newParticipants },
            topic: ADD_PARTICIPANTS,
        });
    }
    const newParticipantIds = newParticipants.map(getParticipantId);
    return { ...result, info, newParticipantIds };
}

export { addEventEntryPairs };
