import { checkRequiredParameters } from '../../../helpers/parameters/checkRequiredParameters.mjs';
import { modifyParticipantsNotice } from '../../notifications/participantNotifications.mjs';
import { EVENT_TYPE, TOURNAMENT_RECORD, VALIDATE } from '../../../constants/attributeConstants.mjs';
import ratingsParameters from '../../../fixtures/ratings/ratingsParameters.mjs';
import { DYNAMIC, SCALE, RATING } from '../../../constants/scaleConstants.mjs';
import { SUCCESS } from '../../../constants/resultConstants.mjs';

function removeRatings(params) {
    const paramsCheck = checkRequiredParameters(params, [
        { [TOURNAMENT_RECORD]: true, [EVENT_TYPE]: true },
        { ratingType: false, [VALIDATE]: (value) => ratingsParameters[value] },
    ]);
    if (paramsCheck.error)
        return paramsCheck;
    const dynamicScaleName = `${params.ratingType}.${DYNAMIC}`;
    const ratingType = params.asDynamic ? dynamicScaleName : params.ratingType;
    const itemType = [SCALE, RATING, params.eventType, ratingType].join('.');
    const participants = params.tournamentRecord.participants ?? [];
    const modifiedParticipants = [];
    for (const participant of participants) {
        if (participant.timeItems) {
            const before = participant.timeItems.length;
            participant.timeItems = participant.timeItems.filter((timeItem) => timeItem.itemType !== itemType);
            if (participant.timeItems.length !== before)
                modifiedParticipants.push(participant);
        }
    }
    if (modifiedParticipants.length) {
        modifyParticipantsNotice({
            tournamentId: params.tournamentRecord.tournamentId,
            participants: modifiedParticipants,
        });
    }
    return { ...SUCCESS };
}

export { removeRatings };
