            sourceMatchUpStatus: matchUpStatus,
            sourceMatchUpId: matchUpId,
            inContextDrawMatchUps,
            winningDrawPosition,
            winnerParticipantId,
            tournamentRecord,
            winnerTargetLink,
            drawDefinition,
            winnerMatchUp,
            dualMatchUp,
            matchUpsMap,
