import { checkAndNotifyUnpublishTournament } from './checkAndNotifyUnpublishTournament.mjs';
import { modifyEventPublishStatus } from '../events/modifyEventPublishStatus.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { addEventTimeItem } from '../timeItems/addTimeItem.mjs';
import { getEventTimeItem } from '../../query/base/timeItems.mjs';
import { addNotice } from '../../global/state/globalState.mjs';
import { TOURNAMENT_RECORD, EVENT } from '../../constants/attributeConstants.mjs';
import { PUBLIC, PUBLISH, STATUS } from '../../constants/timeItemConstants.mjs';
import { UNPUBLISH_EVENT } from '../../constants/topicConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function unPublishEvent({ removePriorValues = true, tournamentRecord, status = PUBLIC, event }) {
    const paramsCheck = requireParams({ tournamentRecord, event }, [TOURNAMENT_RECORD, EVENT]);
    if (paramsCheck.error)
        return paramsCheck;
    const itemType = `${PUBLISH}.${STATUS}`;
    const { timeItem } = getEventTimeItem({
        itemType,
        event,
    });
    const itemValue = timeItem?.itemValue || { [status]: {} };
    delete itemValue[status].structureIds;
    delete itemValue[status].drawDetails;
    delete itemValue[status].drawIds;
    const updatedTimeItem = { itemValue, itemType };
    addEventTimeItem({ event, timeItem: updatedTimeItem, removePriorValues });
    modifyEventPublishStatus({
        statusObject: {
            structureIds: undefined,
            drawIds: undefined,
            seeding: undefined,
        },
        removePriorValues,
        status,
        event,
    });
    addNotice({
        topic: UNPUBLISH_EVENT,
        payload: {
            tournamentId: tournamentRecord.tournamentId,
            eventId: event.eventId,
        },
    });
    checkAndNotifyUnpublishTournament({ tournamentRecord });
    return { eventId: event.eventId, ...SUCCESS };
}

export { unPublishEvent };
